from __future__ import annotations
import json
import sqlite3
from collections.abc import Iterator
from contextlib import contextmanager
from datetime import UTC, datetime
from pathlib import Path
SCHEMA_VERSION = 6

def utc_now() -> str:
    return datetime.now(UTC).isoformat(timespec='microseconds')

def connect(path: Path) -> sqlite3.Connection:
    path.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(path, timeout=30.0, isolation_level=None)
    connection.row_factory = sqlite3.Row
    connection.execute('PRAGMA journal_mode=WAL')
    connection.execute('PRAGMA synchronous=FULL')
    connection.execute('PRAGMA foreign_keys=ON')
    connection.execute('PRAGMA busy_timeout=30000')
    return connection

@contextmanager
def immediate(connection: sqlite3.Connection) -> Iterator[sqlite3.Connection]:
    connection.execute('BEGIN IMMEDIATE')
    try:
        yield connection
    except BaseException:
        connection.rollback()
        raise
    else:
        connection.commit()

def initialize(connection: sqlite3.Connection) -> None:
    connection.executescript("\n        CREATE TABLE IF NOT EXISTS meta (\n            key TEXT PRIMARY KEY,\n            value TEXT NOT NULL\n        );\n\n        CREATE TABLE IF NOT EXISTS roots (\n            id INTEGER PRIMARY KEY,\n            path TEXT NOT NULL UNIQUE,\n            created_at TEXT NOT NULL\n        );\n\n        CREATE TABLE IF NOT EXISTS songs (\n            id INTEGER PRIMARY KEY,\n            ordinal INTEGER NOT NULL UNIQUE,\n            root_id INTEGER NOT NULL REFERENCES roots(id),\n            absolute_path TEXT NOT NULL UNIQUE,\n            relative_path TEXT NOT NULL,\n            title TEXT,\n            artist TEXT,\n            size_bytes INTEGER NOT NULL,\n            mtime_ns INTEGER NOT NULL,\n            missing INTEGER NOT NULL DEFAULT 0 CHECK (missing IN (0, 1)),\n            source_sha256 TEXT,\n            decoded_sha256 TEXT,\n            format TEXT,\n            subtype TEXT,\n            sample_rate INTEGER,\n            channels INTEGER,\n            frames INTEGER,\n            duration_seconds REAL,\n            rights_status TEXT NOT NULL DEFAULT 'unchecked'\n                CHECK (rights_status IN ('unchecked', 'valid', 'missing', 'invalid')),\n            rights_sha256 TEXT,\n            rights_json TEXT,\n            duplicate_of INTEGER REFERENCES songs(id),\n            created_at TEXT NOT NULL,\n            updated_at TEXT NOT NULL\n        );\n\n        CREATE INDEX IF NOT EXISTS songs_source_sha256_idx\n            ON songs(source_sha256);\n        CREATE INDEX IF NOT EXISTS songs_decoded_sha256_idx\n            ON songs(decoded_sha256);\n\n        CREATE TABLE IF NOT EXISTS work_items (\n            song_id INTEGER NOT NULL REFERENCES songs(id),\n            stage TEXT NOT NULL,\n            status TEXT NOT NULL\n                CHECK (status IN ('pending', 'processing', 'complete', 'failed')),\n            attempt_id TEXT,\n            attempts INTEGER NOT NULL DEFAULT 0,\n            started_at TEXT,\n            completed_at TEXT,\n            result_path TEXT,\n            result_sha256 TEXT,\n            last_error TEXT,\n            updated_at TEXT NOT NULL,\n            PRIMARY KEY (song_id, stage)\n        );\n\n        CREATE INDEX IF NOT EXISTS work_items_queue_idx\n            ON work_items(stage, status, song_id);\n\n        CREATE TABLE IF NOT EXISTS events (\n            id INTEGER PRIMARY KEY,\n            at TEXT NOT NULL,\n            kind TEXT NOT NULL,\n            song_id INTEGER REFERENCES songs(id),\n            attempt_id TEXT,\n            detail_json TEXT NOT NULL\n        );\n\n        CREATE TABLE IF NOT EXISTS analysis_runs (\n            id TEXT PRIMARY KEY,\n            kind TEXT NOT NULL CHECK (kind IN ('exploratory', 'primary')),\n            protocol_version TEXT NOT NULL,\n            representation_version TEXT NOT NULL,\n            config_json TEXT NOT NULL,\n            config_sha256 TEXT NOT NULL,\n            input_set_sha256 TEXT NOT NULL,\n            input_song_count INTEGER NOT NULL,\n            status TEXT NOT NULL\n                CHECK (status IN ('pending', 'processing', 'complete', 'failed')),\n            result_path TEXT,\n            result_sha256 TEXT,\n            last_error TEXT,\n            created_at TEXT NOT NULL,\n            completed_at TEXT\n        );\n\n        CREATE UNIQUE INDEX IF NOT EXISTS analysis_runs_identity_idx\n            ON analysis_runs(kind, representation_version, config_sha256, input_set_sha256);\n\n        CREATE TABLE IF NOT EXISTS song_representations (\n            run_id TEXT NOT NULL REFERENCES analysis_runs(id),\n            song_id INTEGER NOT NULL REFERENCES songs(id),\n            status TEXT NOT NULL\n                CHECK (status IN ('pending', 'processing', 'complete', 'failed')),\n            attempt_id TEXT,\n            attempts INTEGER NOT NULL DEFAULT 0,\n            source_decoded_sha256 TEXT NOT NULL,\n            started_at TEXT,\n            completed_at TEXT,\n            artifact_path TEXT,\n            artifact_sha256 TEXT,\n            last_error TEXT,\n            updated_at TEXT NOT NULL,\n            PRIMARY KEY (run_id, song_id)\n        );\n\n        CREATE INDEX IF NOT EXISTS song_representations_queue_idx\n            ON song_representations(run_id, status, song_id);\n\n        CREATE TABLE IF NOT EXISTS similarity_pairs (\n            run_id TEXT NOT NULL REFERENCES analysis_runs(id),\n            left_song_id INTEGER NOT NULL REFERENCES songs(id),\n            right_song_id INTEGER NOT NULL REFERENCES songs(id),\n            metric_version TEXT NOT NULL,\n            mean_wasserstein REAL NOT NULL,\n            mean_hellinger_affinity REAL NOT NULL,\n            scale_distances_json TEXT NOT NULL,\n            detail_json TEXT NOT NULL,\n            PRIMARY KEY (run_id, left_song_id, right_song_id),\n            CHECK (left_song_id < right_song_id)\n        );\n\n        CREATE TABLE IF NOT EXISTS chemistry_snapshots (\n            id TEXT PRIMARY KEY,\n            database_name TEXT NOT NULL,\n            edition TEXT NOT NULL,\n            source_url TEXT NOT NULL,\n            acquired_at TEXT NOT NULL,\n            manifest_path TEXT NOT NULL,\n            manifest_sha256 TEXT NOT NULL,\n            status TEXT NOT NULL CHECK (status IN ('building', 'frozen')),\n            frozen_at TEXT,\n            UNIQUE (database_name, edition, manifest_sha256)\n        );\n\n        CREATE TABLE IF NOT EXISTS chemistry_ingest_items (\n            snapshot_id TEXT NOT NULL REFERENCES chemistry_snapshots(id),\n            molecule_id INTEGER NOT NULL CHECK (molecule_id BETWEEN 1 AND 61),\n            source_kind TEXT NOT NULL,\n            source_url TEXT NOT NULL,\n            status TEXT NOT NULL CHECK (\n                status IN (\n                    'planned', 'awaiting_static_package', 'downloaded',\n                    'normalized', 'failed'\n                )\n            ),\n            expected_source_line_count INTEGER,\n            observed_source_line_count INTEGER,\n            retained_line_count INTEGER,\n            raw_data_path TEXT,\n            raw_data_sha256 TEXT,\n            normalized_path TEXT,\n            normalized_sha256 TEXT,\n            last_error TEXT,\n            updated_at TEXT NOT NULL,\n            PRIMARY KEY (snapshot_id, molecule_id)\n        );\n\n        CREATE TABLE IF NOT EXISTS analysis_chemistry_inputs (\n            run_id TEXT PRIMARY KEY REFERENCES analysis_runs(id),\n            snapshot_id TEXT NOT NULL REFERENCES chemistry_snapshots(id),\n            manifest_sha256 TEXT NOT NULL\n        );\n\n        CREATE TABLE IF NOT EXISTS molecules (\n            snapshot_id TEXT NOT NULL REFERENCES chemistry_snapshots(id),\n            molecule_id INTEGER NOT NULL CHECK (molecule_id BETWEEN 1 AND 61),\n            formula TEXT NOT NULL,\n            common_name TEXT NOT NULL,\n            local_isotopologue_id INTEGER NOT NULL\n                CHECK (local_isotopologue_id = 1),\n            retained_line_count INTEGER NOT NULL CHECK (retained_line_count >= 0),\n            transition_path TEXT NOT NULL,\n            transition_sha256 TEXT NOT NULL,\n            PRIMARY KEY (snapshot_id, molecule_id)\n        );\n\n        CREATE TABLE IF NOT EXISTS molecular_representations (\n            snapshot_id TEXT NOT NULL,\n            molecule_id INTEGER NOT NULL,\n            representation_version TEXT NOT NULL,\n            weighting TEXT NOT NULL CHECK (weighting IN ('einstein_a', 'unweighted')),\n            status TEXT NOT NULL\n                CHECK (status IN ('pending', 'processing', 'complete', 'failed')),\n            attempt_id TEXT,\n            attempts INTEGER NOT NULL DEFAULT 0,\n            retained_line_count INTEGER,\n            unordered_pair_count INTEGER,\n            artifact_path TEXT,\n            artifact_sha256 TEXT,\n            last_error TEXT,\n            started_at TEXT,\n            completed_at TEXT,\n            updated_at TEXT NOT NULL,\n            PRIMARY KEY (\n                snapshot_id, molecule_id, representation_version, weighting\n            ),\n            FOREIGN KEY (snapshot_id, molecule_id)\n                REFERENCES molecules(snapshot_id, molecule_id)\n        );\n\n        CREATE TABLE IF NOT EXISTS real_distance_artifacts (\n            run_id TEXT NOT NULL REFERENCES analysis_runs(id),\n            song_id INTEGER NOT NULL REFERENCES songs(id),\n            status TEXT NOT NULL\n                CHECK (status IN ('pending', 'processing', 'complete', 'failed')),\n            attempt_id TEXT,\n            attempts INTEGER NOT NULL DEFAULT 0,\n            artifact_path TEXT,\n            artifact_sha256 TEXT,\n            last_error TEXT,\n            started_at TEXT,\n            completed_at TEXT,\n            updated_at TEXT NOT NULL,\n            PRIMARY KEY (run_id, song_id)\n        );\n\n        CREATE TABLE IF NOT EXISTS surrogate_shards (\n            run_id TEXT NOT NULL REFERENCES analysis_runs(id),\n            song_id INTEGER NOT NULL REFERENCES songs(id),\n            replicate_start INTEGER NOT NULL CHECK (replicate_start >= 1),\n            replicate_count INTEGER NOT NULL CHECK (replicate_count >= 1),\n            seed_derivation_sha256 TEXT NOT NULL,\n            status TEXT NOT NULL\n                CHECK (status IN ('pending', 'processing', 'complete', 'failed')),\n            attempt_id TEXT,\n            attempts INTEGER NOT NULL DEFAULT 0,\n            artifact_path TEXT,\n            artifact_sha256 TEXT,\n            last_error TEXT,\n            started_at TEXT,\n            completed_at TEXT,\n            updated_at TEXT NOT NULL,\n            PRIMARY KEY (run_id, song_id, replicate_start)\n        );\n\n        CREATE INDEX IF NOT EXISTS surrogate_shards_queue_idx\n            ON surrogate_shards(run_id, status, song_id, replicate_start);\n\n        CREATE TABLE IF NOT EXISTS replicate_statistics (\n            run_id TEXT NOT NULL REFERENCES analysis_runs(id),\n            replicate_index INTEGER NOT NULL CHECK (replicate_index >= 1),\n            dataset_mean_distance REAL NOT NULL,\n            source_shards_sha256 TEXT NOT NULL,\n            PRIMARY KEY (run_id, replicate_index)\n        );\n\n        CREATE TABLE IF NOT EXISTS species_effects (\n            run_id TEXT NOT NULL REFERENCES analysis_runs(id),\n            molecule_id INTEGER NOT NULL CHECK (molecule_id BETWEEN 1 AND 61),\n            mean_surrogate_advantage REAL NOT NULL,\n            detail_json TEXT NOT NULL,\n            PRIMARY KEY (run_id, molecule_id)\n        );\n\n        CREATE TABLE IF NOT EXISTS dataset_statistics (\n            run_id TEXT PRIMARY KEY REFERENCES analysis_runs(id),\n            surrogate_replicates INTEGER NOT NULL CHECK (surrogate_replicates >= 1),\n            t_real REAL NOT NULL,\n            surrogate_mean REAL NOT NULL,\n            surrogate_sd REAL NOT NULL,\n            delta REAL NOT NULL,\n            z_score REAL NOT NULL,\n            monte_carlo_p REAL NOT NULL,\n            probability_superiority REAL NOT NULL,\n            detail_json TEXT NOT NULL,\n            artifact_path TEXT NOT NULL,\n            artifact_sha256 TEXT NOT NULL,\n            completed_at TEXT NOT NULL\n        );\n        ")
    with immediate(connection):
        existing = connection.execute("SELECT value FROM meta WHERE key = 'schema_version'").fetchone()
        if existing is None:
            connection.execute("INSERT INTO meta(key, value) VALUES('schema_version', ?)", (str(SCHEMA_VERSION),))
            connection.execute("INSERT INTO meta(key, value) VALUES('corpus_frozen', '0')")
        elif int(existing['value']) > SCHEMA_VERSION:
            raise RuntimeError(f"unsupported database schema {existing['value']}; expected {SCHEMA_VERSION}")
        elif int(existing['value']) < SCHEMA_VERSION:
            old_version = int(existing['value'])
            if old_version not in (1, 2, 3, 4, 5):
                raise RuntimeError(f'no migration path from database schema {old_version}')
            columns = {str(row['name']) for row in connection.execute('PRAGMA table_info(songs)').fetchall()}
            if 'title' not in columns:
                connection.execute('ALTER TABLE songs ADD COLUMN title TEXT')
            if 'artist' not in columns:
                connection.execute('ALTER TABLE songs ADD COLUMN artist TEXT')
            identity_rows = connection.execute('SELECT id, rights_json FROM songs WHERE (title IS NULL OR artist IS NULL) AND rights_json IS NOT NULL').fetchall()
            for identity_row in identity_rows:
                try:
                    rights_document = json.loads(str(identity_row['rights_json']))
                except json.JSONDecodeError:
                    continue
                title = rights_document.get('title')
                artist = rights_document.get('artist')
                connection.execute('UPDATE songs SET title=COALESCE(title, ?), artist=COALESCE(artist, ?) WHERE id=?', (title.strip() if isinstance(title, str) else None, artist.strip() if isinstance(artist, str) else None, identity_row['id']))
            connection.execute("UPDATE meta SET value=? WHERE key='schema_version'", (str(SCHEMA_VERSION),))
            event(connection, 'schema_migrated', detail={'from': old_version, 'to': SCHEMA_VERSION})

def event(connection: sqlite3.Connection, kind: str, *, song_id: int | None=None, attempt_id: str | None=None, detail: dict | None=None) -> None:
    connection.execute('INSERT INTO events(at, kind, song_id, attempt_id, detail_json) VALUES(?, ?, ?, ?, ?)', (utc_now(), kind, song_id, attempt_id, json.dumps(detail or {}, sort_keys=True)))

def get_meta(connection: sqlite3.Connection, key: str, default: str | None=None) -> str | None:
    row = connection.execute('SELECT value FROM meta WHERE key = ?', (key,)).fetchone()
    return default if row is None else str(row['value'])

def set_meta(connection: sqlite3.Connection, key: str, value: str) -> None:
    connection.execute('INSERT INTO meta(key, value) VALUES(?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value', (key, value))
